  const months = Array.from({ length: span }, (_, i) => {
    const d = new Date(clock.getFullYear(), clock.getMonth() + i, 1);
    const m = monthShape(d.getFullYear(), d.getMonth() + 1);
    return { ...m, name: `${MONTHS_FULL[m.idx - 1]} ${m.year}` };
  });
